export function fatigueDecision(history=[],{now=Date.now(),windowMs=86400000,maxPerWindow=4,cooldownMs=3600000,safety=false}={}){if(safety)return {allow:true,reason:'SAFETY_OVERRIDE'};const recent=history.filter(x=>now-Number(x.sentAt||0)<=windowMs);if(recent.length>=maxPerWindow)return {allow:false,reason:'WINDOW_LIMIT'};const last=Math.max(0,...recent.map(x=>Number(x.sentAt||0)));if(last&&now-last<cooldownMs)return {allow:false,reason:'COOLDOWN'};return {allow:true,reason:'OK'}}
